import{_ as o,o as a,c,ai as r}from"./chunks/framework.Ba-VnP44.js";const b=JSON.parse('{"title":"CRM 客户关系管理 · OpenBiz 第四个独立消费者","description":"","frontmatter":{},"headers":[],"relativePath":"apps/openbiz/crm.md","filePath":"apps/openbiz/crm.md"}'),i={name:"apps/openbiz/crm.md"};function n(p,e,t,d,l,s){return a(),c("div",null,[...e[0]||(e[0]=[r('<h1 id="crm-客户关系管理-·-openbiz-第四个独立消费者" tabindex="-1">CRM 客户关系管理 · OpenBiz 第四个独立消费者 <a class="header-anchor" href="#crm-客户关系管理-·-openbiz-第四个独立消费者" aria-label="Permalink to “CRM 客户关系管理 · OpenBiz 第四个独立消费者”">​</a></h1><blockquote><p>现为独立应用 <code>openbiz-crm-app</code>（<code>E:/8.cangku/for-job/openbiz-crm-app</code>）：独立后端（端口 18084）+ 独立前端（Vue3/TS）+ 独立数据库 <code>openbiz_crm</code>。</p></blockquote><blockquote><p>实证：OpenBiz 母仓 business 域仅有 Customer 实体，CRM 的线索 / 商机 / 跟进需自建。按 OpenBiz 命名约定自建 <code>openbiz_crm_*</code> 表，在其多租户基座之上实现「客户 + 商机」最小闭环与销售漏斗雏形。验证「百套流水线」对 A 类第 2 个系统的可复制性。</p></blockquote><h2 id="复用与自建" tabindex="-1">复用与自建 <a class="header-anchor" href="#复用与自建" aria-label="Permalink to “复用与自建”">​</a></h2><ul><li><strong>复用</strong>：OpenBiz <code>openbiz-saas-core</code> 多租户（TenantContext / TenantService / 自动装配）、RuoYi 登录外壳</li><li><strong>自建</strong>：<code>openbiz_crm_customer</code> / <code>openbiz_crm_opportunity</code> 表 + Mapper / Service / Controller <ul><li>客户状态机：<code>NEW → ACTIVE → CHURNED</code>，活动态可转 <code>INVALID</code>（逻辑删除）</li><li>商机状态机：<code>DRAFT → NEGOTIATING → WON</code> / <code>DRAFT → NEGOTIATING → LOST</code>，<code>DRAFT/NEGOTIATING → CANCELLED</code>；WON/LOST/CANCELLED 为终态</li><li>统计：<code>GET /api/crm/opportunities/stats</code> 按阶段聚合（销售漏斗雏形）</li></ul></li></ul><h2 id="业务闭环-e2e-已验证" tabindex="-1">业务闭环（E2E 已验证） <a class="header-anchor" href="#业务闭环-e2e-已验证" aria-label="Permalink to “业务闭环（E2E 已验证）”">​</a></h2><p>登录 → 建客户(NEW) → 激活(ACTIVE) → 建商机(DRAFT/OPEN) → 谈判(NEGOTIATING) → 赢单(WON) → 阶段统计正确 → WON 再谈判 / NEW 直接流失均被拦截 <code>ILLEGAL_TRANSITION</code> → 数据落库可重拉。</p><h2 id="工程位置" tabindex="-1">工程位置 <a class="header-anchor" href="#工程位置" aria-label="Permalink to “工程位置”">​</a></h2><p><code>E:/8.cangku/for-job/openbiz-crm-app</code>（端口 18084，含 README 与 E2E 脚本）</p><h2 id="价值" tabindex="-1">价值 <a class="header-anchor" href="#价值" aria-label="Permalink to “价值”">​</a></h2><p>与工单 / MES / PMS 共同坐实「百套流水线」可复制：第 4 个系统按脚手架数小时内从零跑通 E2E。</p><hr><p>上一级：<a href="/my-vitepress-site/apps/openbiz/">OpenBiz 试水实证</a></p>',13)])])}const m=o(i,[["render",n]]);export{b as __pageData,m as default};
